from contextlib import asynccontextmanager
from fastapi import FastAPI, Request, HTTPException
from fastapi.responses import StreamingResponse, JSONResponse
from fastapi.middleware.cors import CORSMiddleware
import uvicorn

active_sessions: Dict[str, List[Dict[str, Any]]] = {}
conversation_history: Dict[str, List[Dict[str, Any]]] = {}
session_timestamps: Dict[str, int] = {}
registered_users: Dict[str, str] = {}

@asynccontextmanager
async def lifespan(app: FastAPI):
    yield

app = FastAPI(lifespan=lifespan)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

def estimate_tokens(text: str) -> int:
    if not isinstance(text, str):
        text = json.dumps(text) if isinstance(text, (dict, list)) else str(text)
    return len(text) // 4 + 20

def enforce_128k_limit(messages: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    if not isinstance(messages, list):
        return []
    total = 0
    result = []
    for msg in reversed(messages):
        content = msg.get("content", "")
        total += estimate_tokens(content)
        if total > 128000:
            break
        result.append(msg)
    return list(reversed(result))

def generate_thinking_step(content: str) -> str:
    if len(content) > 180:
        preview = content[:180] + "..."
    else:
        preview = content
    return f"Analyzing query in full 128000 token context window with temperature exactly 0 for deterministic output...\nProcessing user input: {preview}\nRecalling relevant knowledge up to current date...\nFormulating structured step-by-step reasoning with maximum helpfulness and accuracy..."

