        conversation_history[session_id] = []
    conversation_history[session_id].extend(new_messages)
    conversation_history[session_id] = enforce_128k_limit(conversation_history[session_id])
    active_sessions[session_id] = conversation_history[session_id]
    if session_id not in session_timestamps:
        session_timestamps[session_id] = int(time.time())
    last_user_content = ""
    for m in reversed(conversation_history[session_id]):
        if m.get("role") == "user":
            last_user_content = str(m.get("content", ""))
            break
