    await asyncio.sleep(0.35)
    thinking_text = generate_thinking_step(last_user_content)
    for i in range(0, len(thinking_text), 35):
        chunk = thinking_text[i:i+35]
        yield f'data: {json.dumps({"type": "reasoning", "content": chunk, "step": "Structured reasoning with full context"})}\n\n'
        await asyncio.sleep(0.028)
    yield f'data: {json.dumps({"type": "reasoning_end"})}\n\n'
    await asyncio.sleep(0.18)
    if is_agent:
        yield f'data: {json.dumps({"type": "search_start", "query": last_user_content[:120]})}\n\n'
        await asyncio.sleep(0.42)
        yield f'data: {json.dumps({"type": "search_result", "results": [{"title": "Claude Opus 4.7 full capabilities overview", "url": ""}, {"title": "128k context window technical details", "url": ""}], "total": 2})}\n\n'
