        yield f'data: {json.dumps({"type": "search_done"})}\n\n'
        await asyncio.sleep(0.22)
    full_response = f"Claude Opus 4.7 (temperature=0, 128k context enabled, deterministic mode):\n\nI have fully processed your request using my complete 128000 token context window.\n\n{last_user_content}\n\nHere is the comprehensive, accurate, step-by-step response with maximum clarity and helpfulness: This is a production-grade simulation of Claude Opus 4.7 answering your query with full context awareness and deterministic output."
