@app.get("/api/sessions")
async def api_sessions():
    sessions = []
    for sid, msgs in conversation_history.items():
        if msgs:
            preview_msg = next((m for m in reversed(msgs) if m.get("role") == "user"), msgs[-1] if msgs else {})
            preview = str(preview_msg.get("content", ""))[:80]
            sessions.append({
