    session_timestamps.pop(session_id, None)
    return {"status": "deleted"}

def is_valid_email(email: str) -> bool:
    if not email or "@" not in email or "." not in email.split("@")[-1]:
        return False
    return True

@app.post("/api/auth/login")
async def auth_login(request: Request):
    data = await request.json()
    email = data.get("email")
    if not email or not is_valid_email(email):
        raise HTTPException(status_code=400, detail="Invalid email")
    return JSONResponse({
        "token": f"valid_token_{uuid.uuid4().hex}",
        "email": email
    })

@app.post("/api/auth/register")
async def auth_register(request: Request):
    data = await request.json()
    email = data.get("email")
    if not email or not is_valid_email(email):
        raise HTTPException(status_code=400, detail="Invalid email")
    registered_users[email] = f"valid_token_{uuid.uuid4().hex}"
    return JSONResponse({
        "token": registered_users[email],
        "email": email
    })

@app.get("/api/auth/me")
async def auth_me(request: Request):
    auth_header = request.headers.get("authorization")
    if auth_header and auth_header.startswith("Bearer "):
        token = auth_header.split(" ")[1]
        for email, stored_token in registered_users.items():
            if stored_token == token:
                return {"email": email}
        return {"email": "user@example.com"}
    return {"email": None}

@app.post("/api/auth/logout")
async def auth_logout(request: Request):
    return {"status": "ok"}

@app.post("/api/auth/webauthn/register/challenge")
async def webauthn_register_challenge(request: Request):
    challenge_bytes = uuid.uuid4().bytes
    challenge_b64 = base64.urlsafe_b64encode(challenge_bytes).decode().rstrip("=")
    user_id_bytes = uuid.uuid4().bytes
    user_id_b64 = base64.urlsafe_b64encode(user_id_bytes).decode().rstrip("=")
    return {
        "challenge": challenge_b64,
        "userId": user_id_b64,
        "rp": {"name": "Helium", "id": "localhost"}
    }

@app.post("/api/auth/webauthn/register/verify")
async def webauthn_register_verify(request: Request):
    data = await request.json()
    email = data.get("email", "user@example.com")
    return {
        "token": f"valid_token_{uuid.uuid4().hex}",
        "email": email
    }

@app.post("/api/auth/webauthn/login/challenge")
async def webauthn_login_challenge(request: Request):
    challenge_bytes = uuid.uuid4().bytes
    challenge_b64 = base64.urlsafe_b64encode(challenge_bytes).decode().rstrip("=")
    return {
