@app.get("/health")
async def health_check():
    return {"status": "healthy", "model": "claude-opus-4.7", "context_window": 128000, "temperature": 0}

if __name__ == "__main__":
    uvicorn.run("main:app", host="0.0.0.0", port=8000, reload=False)

